const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c <= 32) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

function readTree(n) {
  const adj = Array.from({ length: n }, () => []);
  for (let i = 0; i < n - 1; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;
    adj[a].push(b);
    adj[b].push(a);
  }
  return adj;
}

function findCenter(adj) {
  const n = adj.length;

  function farthestFrom(start) {
    const dist = new Int32Array(n);
    dist.fill(-1);
    const queue = new Int32Array(n);
    let head = 0;
    let tail = 0;
    queue[tail++] = start;
    dist[start] = 0;
    let farthest = start;

    while (head < tail) {
      const u = queue[head++];
      if (dist[u] > dist[farthest]) farthest = u;
      for (const v of adj[u]) {
        if (dist[v] === -1) {
          dist[v] = dist[u] + 1;
          queue[tail++] = v;
        }
      }
    }
    return farthest;
  }

  const endpoint = farthestFrom(0);
  const parent = new Int32Array(n);
  parent.fill(-1);
  const dist = new Int32Array(n);
  dist.fill(-1);
  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;
  queue[tail++] = endpoint;
  dist[endpoint] = 0;
  let farthest = endpoint;

  while (head < tail) {
    const u = queue[head++];
    if (dist[u] > dist[farthest]) farthest = u;
    for (const v of adj[u]) {
      if (dist[v] === -1) {
        dist[v] = dist[u] + 1;
        parent[v] = u;
        queue[tail++] = v;
      }
    }
  }

  const path = [];
  for (let v = farthest; v !== -1; v = parent[v]) path.push(v);
  return path[Math.floor((path.length - 1) / 2)] + 1;
}

const n = nextInt();
const m = nextInt();
const circle = readTree(n);
const square = readTree(m);

console.log(`${findCenter(circle)} ${findCenter(square)}`);
